if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Play Mode required");
var router=UnityEngine.Object.FindFirstObjectByType<ClashRoyaleUI.UIScreenRouter>();
var root=router.Screens.First(s=>s.id==ClashRoyaleUI.ScreenId.BattlePass).view;
var scroll=root.GetComponentInChildren<UnityEngine.UI.ScrollRect>();
var layers=root.GetComponentsInChildren<ClashRoyaleUI.FigmaLayer>(true);
var axis=layers.Single(l=>l.nodeId=="158:68").transform;
var header=layers.Single(l=>l.nodeId=="158:79").transform;
var claim=layers.Single(l=>l.nodeId=="158:72").transform;
var headerBefore=header.position;var claimBefore=claim.position;
var axisBefore=axis.position;var contentBefore=scroll.content.position;
var point=UnityEngine.RectTransformUtility.WorldToScreenPoint(null,scroll.viewport.TransformPoint(scroll.viewport.rect.center));
var pointer=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=point,pressPosition=point,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};
var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();
UnityEngine.EventSystems.EventSystem.current.RaycastAll(pointer,hits);
if(hits.Count==0)throw new System.Exception("No pointer hit on reward panel");
var target=hits[0].gameObject;
var handler=UnityEngine.EventSystems.ExecuteEvents.GetEventHandler<UnityEngine.EventSystems.IDragHandler>(target);
if(handler!=scroll.gameObject)throw new System.Exception("Reward panel does not route mouse drag to ScrollRect");
pointer.pointerPressRaycast=hits[0];pointer.pointerCurrentRaycast=hits[0];pointer.pointerDrag=handler;
UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(target,pointer,UnityEngine.EventSystems.ExecuteEvents.initializePotentialDrag);
UnityEngine.EventSystems.ExecuteEvents.Execute(handler,pointer,UnityEngine.EventSystems.ExecuteEvents.beginDragHandler);
pointer.dragging=true;pointer.position=point+new UnityEngine.Vector2(0,330);pointer.delta=new UnityEngine.Vector2(0,330);
UnityEngine.EventSystems.ExecuteEvents.Execute(handler,pointer,UnityEngine.EventSystems.ExecuteEvents.dragHandler);
UnityEngine.EventSystems.ExecuteEvents.Execute(handler,pointer,UnityEngine.EventSystems.ExecuteEvents.endDragHandler);
scroll.StopMovement();UnityEngine.Canvas.ForceUpdateCanvases();
var axisDelta=axis.position-axisBefore;var contentDelta=scroll.content.position-contentBefore;
var result=new{mouseHit=target.name,dragHandler=handler.name,contentOffset=scroll.content.anchoredPosition.y,axisMovesWithRewards=(axisDelta-contentDelta).sqrMagnitude<0.001f,headerFixed=(header.position-headerBefore).sqrMagnitude<0.001f,claimFixed=(claim.position-claimBefore).sqrMagnitude<0.001f,scrollFraction=scroll.verticalNormalizedPosition};
if(result.contentOffset<300||!result.axisMovesWithRewards||!result.headerFixed||!result.claimFixed)throw new System.Exception("Drag validation failed");
System.IO.File.WriteAllText("DesignReference/Validation/Pass40/drag-result.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));
UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("DesignReference/Validation/Pass40/Dragged.png"));
return result;
